import json,pathlib
for p in pathlib.Path('world').rglob('*.json'):
 if 'mission' in str(p):
  d=json.loads(p.read_text())
  def walk(x):
   if isinstance(x,dict):
    if x.get('mission_id')=='PARSER-PARITY-DELIVERY-EXAMPLE': print(json.dumps(x))
    else:
     for v in x.values(): walk(v)
   elif isinstance(x,list):
    for v in x: walk(v)
  walk(d)
